import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"moparticles/getting-started.md","filePath":"moparticles/getting-started.md","lastUpdated":1788316873000}'),n={name:"moparticles/getting-started.md"};function o(r,e,l,p,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Version</th></tr></thead><tbody><tr><td>Server software</td><td>Paper (1.21.x — built and tested on 1.21.11)</td></tr><tr><td>Java</td><td>21+</td></tr><tr><td>Client</td><td>1.21.x (item-display models require a recent client)</td></tr></tbody></table><blockquote><p><strong>Note:</strong> MoParticles is a Paper plugin. It will not run on plain Spigot, CraftBukkit, or BungeeCord.</p></blockquote><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li><p>Download the latest <code>MoParticles-x.x-all.jar</code> from the <a href="https://github.com/Chest-Solutions/MoParticles/releases" target="_blank" rel="noreferrer">releases page</a>.</p></li><li><p>Drop the jar into your server&#39;s <code>plugins/</code> folder.</p></li><li><p>Start (or restart) the server. On boot you should see:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[MoParticles] Loaded 3 particle effect(s).</span></span>
<span class="line"><span>MoParticles v1.1.0 enabled.</span></span></code></pre></div></li><li><p>That&#39;s it. There is no configuration file to edit — the plugin works out of the box.</p></li></ol><h2 id="your-first-effect" tabindex="-1">Your first effect <a class="header-anchor" href="#your-first-effect" aria-label="Permalink to &quot;Your first effect&quot;">​</a></h2><p>With the server running, give a player the <code>moparticles</code> command permission (or run it as an operator) and try:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/moparticles playhere snowstorm:rainbow</span></span></code></pre></div><p>This plays the bundled rainbow effect at your current location with a default radius of 10 blocks.</p><h2 id="the-resource-pack" tabindex="-1">The resource pack <a class="header-anchor" href="#the-resource-pack" aria-label="Permalink to &quot;The resource pack&quot;">​</a></h2><p>MoParticles generates a resource pack on boot at:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/MoParticles/generated/resourcepack.zip</span></span></code></pre></div><p>The pack contains the <strong>item models</strong> and <strong>particle textures</strong> that the animations are built from. Players need this pack installed for the effects to render correctly:</p><ul><li>Share the zip with your players (a download link, a media folder, or your launcher&#39;s pack directory).</li><li>If you add new particle files later, the pack is regenerated the next time the plugin loads — redistribute the updated zip when you do.</li></ul><blockquote><p>The pack is regenerated from your <code>particles/</code> and <code>textures/</code> folders, so it always matches what&#39;s loaded.</p></blockquote><h2 id="folder-layout" tabindex="-1">Folder layout <a class="header-anchor" href="#folder-layout" aria-label="Permalink to &quot;Folder layout&quot;">​</a></h2><p>Everything MoParticles owns lives under <code>plugins/MoParticles/</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/MoParticles/</span></span>
<span class="line"><span>├── particles/          # your .json effect files (3 bundled by default)</span></span>
<span class="line"><span>├── textures/</span></span>
<span class="line"><span>│   └── particle/       # texture files (circle.png, cube.png bundled)</span></span>
<span class="line"><span>└── generated/</span></span>
<span class="line"><span>    └── resourcepack.zip</span></span></code></pre></div><h2 id="configuration-optional" tabindex="-1">Configuration (optional) <a class="header-anchor" href="#configuration-optional" aria-label="Permalink to &quot;Configuration (optional)&quot;">​</a></h2><p>MoParticles has zero required settings. If you need to debug, create <code>plugins/MoParticles/config.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Log extra diagnostics to the console while effects are playing</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">debug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>Then restart the server (or use <code>/moparticles reload</code> after editing).</p><h2 id="building-from-source" tabindex="-1">Building from source <a class="header-anchor" href="#building-from-source" aria-label="Permalink to &quot;Building from source&quot;">​</a></h2><p>If you prefer to build MoParticles yourself, you need <strong>JDK 21</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Chest-Solutions/MoParticles.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MoParticles</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shadowJar</span></span></code></pre></div><p>The shaded jar is written to <code>build/libs/</code>.</p>`,27)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
